 display: flex;
 align-items: center;
 justify-content: center;
 width: 100%;
 height: 100%;
}

.start-card {
 background: rgba(26, 26, 46, 0.95);
 border: 2px solid #56B4E9;
 border-radius: 12px;
 padding: 48px;
 text-align: center;
 box-shadow: 0 0 30px rgba(86, 180, 233, 0.15);
}

.start-title {
 font-size: 64px;
 font-weight: 900;
 background: linear-gradient(135deg, #56B4E9, #CC79A7, #E69F00);
 -webkit-background-clip: text;
 -webkit-text-fill-color: transparent;
 background-clip: text;
 margin-bottom: 8px;
 letter-spacing: 8px;
}

.start-subtitle {
 color: #888;
 font-size: 14px;
 margin-bottom: 36px;
 letter-spacing: 2px;
 text-transform: uppercase;
}

.start-form {
 display: flex;
 flex-direction: column;
 gap: 12px;
 margin: 0 0 32px 0;
}

.start-label {
 font-size: 14px;
 color: #aaa;
 text-align: left;
}

.start-input {
 padding: 12px 16px;
 background: #16213e;
 border: 1px solid #333;
 border-radius: 6px;
 color: #fff;
 font-size: 16px;
 outline: none;
 transition: border-color 0.2s;
}

.start-input:focus {
 border-color: #56B4E9;
}

.start-button {
 padding: 14px 32px;
 background: linear-gradient(135deg, #56B4E9, #0072B2);
 border: none;
 border-radius: 6px;
 color: #fff;
 font-size: 18px;
 font-weight: 700;
 cursor: pointer;
 transition: opacity 0.2s;
 margin-top: 8px;
 letter-spacing: 1px;
}

.start-button:disabled {
 opacity: 0.4;
 cursor: not-allowed;
}

.start-button:not(:disabled):hover {
 opacity: 0.85;
}

.start-controls {
 color: #666;
 font-size: 13px;
 display: flex;
 flex-direction: column;
 gap: 4px;
 align-items: center;
}

.start-controls p {
 margin-bottom: 2px;
 color: #888;
}

.start-controls span {
 display: block;
