 background: rgba(26, 26, 46, 0.92);
 border: 1px solid #2a2a4e;
 border-radius: 8px;
 padding: 16px;
 min-width: 200px;
 max-height: 600px;
 overflow-y: auto;
}

.hs-title {
 font-size: 13px;
 text-transform: uppercase;
 letter-spacing: 2px;
 color: #E69F00;
 margin: 0 0 12px 0;
 text-align: center;
}

.hs-empty {
 color: #666;
 font-style: italic;
 text-align: center;
 font-size: 13px;
}

.hs-table {
 width: 100%;
 border-collapse: collapse;
}

.hs-table th {
 font-size: 10px;
 text-transform: uppercase;
 letter-spacing: 1px;
 color: #888;
 padding: 4px 6px;
 border-bottom: 1px solid #333;
 text-align: left;
}

.hs-table td {
 padding: 5px 6px;
 border-bottom: 1px solid #1a1a2e;
 font-size: 13px;
 color: #ccc;
}

.hs-rank-1 td {
 color: #E69F00;
 font-weight: 700;
}

.hs-rank-2 td {
 color: #c0c0c0;
}

.hs-rank-3 td {
 color: #CC79A7;
}","style"),insertStyle(".tetris-container {
 display: flex;
 gap: 24px;
 align-items: flex-start;
 outline: none;
}

.tetris-canvas {
 border: 2px solid #56B4E9;
 border-radius: 4px;
 box-shadow: 0 0 20px rgba(86, 180, 233, 0.2);
 display: block;
}

.tetris-sidebar {
 display: flex;
 flex-direction: column;
 gap: 12px;
 min-width: 140px;
}

.sidebar-section {
 background: rgba(26, 26, 46, 0.9);
 border: 1px solid #2a2a4e;
 border-radius: 8px;
 padding: 12px 16px;
}

.sidebar-section h3 {
 font-size: 11px;
 text-transform: uppercase;
 letter-spacing: 2px;
 color: #56B4E9;
 margin: 0 0 8px 0;
}

.preview-canvas {
 background: #1a1a2e;
 border-radius: 4px;
 display: block;
}

.player-name {
 font-size: 16px;
 font-weight: 600;
 color: #f0f0f0;
 word-break: break-word;
 margin: 0;
}

.stat-value {
 font-size: 24px;
 font-weight: 700;
 color: #fff;
 font-variant-numeric: tabular-nums;
 margin: 0;
}

/* Lives */
.lives-display {
 font-size: 22px;
 letter-spacing: 4px;
 margin: 0;
}

/* Swap counter */
.swap-counter {
 display: flex;
 align-items: baseline;
 gap: 4px;
 margin: 0;
}

.swap-available {
 font-size: 26px;
 font-weight: 700;
 color: #E69F00;
 font-variant-numeric: tabular-nums;
}

.swap-empty {
 font-size: 26px;
 font-weight: 700;
 color: #555;
 font-variant-numeric: tabular-nums;
}

.swap-label {
 font-size: 13px;
 color: #888;
}

/* Pause badge */
.pause-badge {
 background: rgba(86, 180, 233, 0.15);
 border: 2px solid #56B4E9;
 border-radius: 8px;
 padding: 10px 16px;
 text-align: center;
 font-size: 16px;
 font-weight: 700;
 color: #56B4E9;
 letter-spacing: 3px;
 animation: pulse-badge 1.5s ease-in-out infinite;
}

@keyframes pulse-badge {
 0%, 100% {
 opacity: 1;
 }
 50% {
 opacity: 0.5;
 }
}
/* Restart button */
.restart-btn {
 padding: 10px 16px;
 background: linear-gradient(135deg, #D55E00, #a04000);
 border: none;
 border-radius: 6px;
 color: #fff;
 font-size: 15px;
 font-weight: 700;
 cursor: pointer;
 transition: opacity 0.2s;
 letter-spacing: 1px;
 text-align: center;
}

.restart-btn:hover {
 opacity: 0.85;
}

/* Controls hint */
.controls-hint {
 background: rgba(26, 26, 46, 0.7);
 border: 1px solid #2a2a4e;
 border-radius: 8px;
 padding: 10px 14px;
 font-size: 11px;
 color: #666;
 line-height: 1.6;
}

.controls-hint p {
 margin: 0;
}","style"),insertStyle(".gameover-screen {
 display: flex;
 align-items: center;
 justify-content: center;
 width: 100%;
 height: 100%;
}

.gameover-card {
 background: rgba(26, 26, 46, 0.95);
 border: 2px solid #D55E00;
 border-radius: 12px;
 padding: 40px;
 text-align: center;
 box-shadow: 0 0 30px rgba(213, 94, 0, 0.15);
 max-width: 500px;
 width: 100%;
}

.gameover-title {
 font-size: 48px;
 font-weight: 900;
 color: #D55E00;
 margin-bottom: 24px;
 letter-spacing: 4px;
 text-shadow: 0 0 20px rgba(213, 94, 0, 0.5);
}

.gameover-stats {
 display: flex;
 justify-content: center;
 gap: 32px;
 margin-bottom: 32px;
}

.gameover-stat {
 display: flex;
 flex-direction: column;
 gap: 4px;
}

.gameover-stat span {
 font-size: 12px;
 text-transform: uppercase;
 letter-spacing: 1px;
 color: #888;
}

.gameover-stat strong {
 font-size: 28px;
 color: #fff;
}

.high-scores {
 margin-bottom: 24px;
}

.high-scores h2 {
 font-size: 16px;
 color: #E69F00;
 margin-bottom: 12px;
 letter-spacing: 1px;
}

.no-scores {
 color: #666;
 font-style: italic;
}

.scores-table {
 width: 100%;
 border-collapse: collapse;
}

.scores-table th {
 font-size: 11px;
 text-transform: uppercase;
 letter-spacing: 1px;
 color: #888;
 padding: 6px 8px;
 border-bottom: 1px solid #333;
 text-align: left;
}

.scores-table td {
 padding: 8px;
 border-bottom: 1px solid #1a1a2e;
 font-size: 14px;
}

.scores-table tbody tr:nth-child(1) td {
 color: #E69F00;
 font-weight: 700;
}

.scores-table tbody tr:nth-child(2) td {
 color: #c0c0c0;
}

.scores-table tbody tr:nth-child(3) td {
 color: #CC79A7;
}

.restart-button {
 padding: 14px 40px;
 background: linear-gradient(135deg, #56B4E9, #0072B2);
 border: none;
 border-radius: 6px;
 color: #fff;
 font-size: 18px;
 font-weight: 700;
 cursor: pointer;
 transition: opacity 0.2s;
 letter-spacing: 1px;
}

.restart-button:hover {
 opacity: 0.85;
}","style"),insertStyle('* {
